DO $guard$ BEGIN PERFORM 1 FROM public.offer_products WHERE id='afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf' AND updated_at='2026-10-12T09:27:50.374082+00:00'::timestamptz FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Produkt zmienił się od odczytu; przerwano zapis'; END IF; END $guard$;
UPDATE public.offer_products SET (sales_packages,sales_packages_enabled,price_net,base_price,price_gross,unit,min_quantity,description,offer_description,public_description,offer_additional_requirements,updated_at)=(SELECT sales_packages,sales_packages_enabled,price_net,base_price,price_gross,unit,min_quantity,description,offer_description,public_description,offer_additional_requirements,now() FROM jsonb_populate_record(NULL::public.offer_products,'{"sales_packages": [{"id": "7724aa5e-d3e9-4095-8a21-8846b436c2d4", "name": "Basic — dekor filmowy", "description": "Filmowa aranżacja wejścia i sali, strefa zdjęć oraz światło dekoracyjne.", "included_label": "Wejście · scenografia · strefa zdjęć · światło", "element_ids": ["4b429486-eff9-4a74-9396-41293008bf08", "fd24e51f-3bd7-45dd-8f5e-3c9e9e233b40", "30b22edc-84fb-4b2d-830c-e61a0b2ff64c", "1d9190fb-21a4-44a3-ba44-b0761300577d"], "price_net": 6000, "bonus": "", "highlighted": false, "image_path": "assets/afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf/offer-image-1791792427744.jpg", "image_alt": "Przykładowa aranżacja wejścia w klimacie filmowym — realizacja MAVINCI.", "extension_price_net_per_hour": null, "cost_items": null, "resources": null, "price_on_request": false, "include_product_addons": false}, {"id": "4bea0e95-f894-4ae1-9dca-9653ed4dcea9", "name": "Dekor i stoły", "description": "Pełny zakres Basic oraz dekoracja do 12 stołów w uzgodnionym standardzie.", "included_label": "Basic + dekoracja do 12 stołów", "element_ids": ["4b429486-eff9-4a74-9396-41293008bf08", "fd24e51f-3bd7-45dd-8f5e-3c9e9e233b40", "30b22edc-84fb-4b2d-830c-e61a0b2ff64c", "b4bba897-2bc5-4a97-9892-f9aa584b15d0", "1d9190fb-21a4-44a3-ba44-b0761300577d"], "price_net": 10000, "bonus": "", "highlighted": false, "image_path": "assets/afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf/filmowa-noc-20261012/element-4.jpg", "image_alt": "Przykładowa dekoracja stołów w klimacie gali filmowej — realizacja MAVINCI.", "extension_price_net_per_hour": null, "cost_items": null, "resources": null, "price_on_request": false, "include_product_addons": false}, {"id": "26c8c8e9-1042-4926-b8d0-a7b9b1f62617", "name": "Dekor, stoły i LED 15 m²", "description": "Dekoracja sali i do 12 stołów, uzupełniona ekranem LED o powierzchni 15 m².", "included_label": "Basic + do 12 stołów + ekran LED 15 m²", "element_ids": ["4b429486-eff9-4a74-9396-41293008bf08", "fd24e51f-3bd7-45dd-8f5e-3c9e9e233b40", "30b22edc-84fb-4b2d-830c-e61a0b2ff64c", "b4bba897-2bc5-4a97-9892-f9aa584b15d0", "1d9190fb-21a4-44a3-ba44-b0761300577d", "48fb7e93-654e-4b32-af69-0a309f70d8cb"], "price_net": 17000, "bonus": "", "highlighted": false, "image_path": "assets/afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf/variants/48fb7e93-654e-4b32-af69-0a309f70d8cb-a1e9c81f-3c70-4278-add8-50873f84e4fd.jpg", "image_alt": "Ekran LED w oprawie gali MAVINCI — zdjęcie inspiracyjne; format 15 m² dopasowujemy do sali.", "extension_price_net_per_hour": null, "cost_items": null, "resources": null, "price_on_request": false, "include_product_addons": false}], "sales_packages_enabled": true, "price_net": 6000, "base_price": 6000, "price_gross": 7380.0, "unit": "pakiet", "min_quantity": 1, "description": "Dekoracja filmowa sali około 360 m² dla 90–100 gości. Trzy pełne pakiety: Basic — dekor 6000 zł netto; dekor i do 12 stołów 10000 zł netto; dekor, do 12 stołów i ekran LED 15 m² 17000 zł netto. Dostępne elementy dobieramy do uzgodnionej aranżacji. Nowe bannery, PCV i dodatkowe stoły wyceniane osobno. Logistyka oraz warunki montażu do doprecyzowania w ofercie.", "offer_description": "Aranżacja w klimacie premiery i gali filmowej. Pakiet Basic obejmuje wejście z dywanem, scenografię, strefę zdjęć i światło dekoracyjne. Kolejny dodaje dekorację do 12 stołów, a pełny zestaw także ekran LED 15 m². Ceny dotyczą sali około 360 m² dla 90–100 gości. Nowe bannery i postacie PCV są dodatkami. Zdjęcia pokazują nasze realizacje; ilości, standard dekoracji i warunki techniczne określa oferta.", "public_description": "Filmowa noc — dekoracja tematyczna\n\nAranżacja sali inspirowana premierą kinową i galą filmową. Łączymy czerwony dywan, dekoracyjne motywy taśmy filmowej, tła, figury i światło z oprawą stołów. Zakres budujemy z wybranych elementów, odpowiednio do miejsca, liczby gości i budżetu. Zdjęcia pokazują nasze wcześniejsze realizacje; ostateczny zestaw i ilości określa oferta.\n\nWejście na premierę\nCzerwony dywan oraz kordony tworzą filmowe wejście. Mogą mu towarzyszyć figury i dekoracje przypominające taśmę filmową. Długość dywanu, liczbę słupków i rozmieszczenie dobieramy do wejścia oraz komunikacji w obiekcie.\n\nScenografia i tła filmowe\nWykorzystujemy motywy gwiazd kina, taśmy i szpule filmowe, figury oraz dostępne tła. Rozstawiamy je jako akcenty wejścia, sali i miejsca do zdjęć. Konkretne wzory, ilości, wymiary oraz stan dekoracji potwierdzamy przed realizacją. Nowy motyw lub personalizowany wydruk wymaga przygotowania projektu i osobnej kalkulacji.\n\nMiejsce do zdjęć\nMożna zbudować kameralny plan filmowy z fotelem reżysera, rekwizytami i odpowiednim tłem. Stanowi on dekoracyjną przestrzeń do zdjęć wykonywanych przez gości. Fotograf, fotolustro lub fotobudka są dodatkowymi usługami. Rekwizyty występujące także w dekoracji wejścia liczymy jeden raz, zgodnie z ich faktycznym rozmieszczeniem.\n\nDekoracja stołów\nProponujemy połączenie czerni, czerwieni lub burgundu ze złotymi akcentami. Zakres może obejmować uzgodnione kompozycje, tematyczne dodatki, numerację, serwetki i dekoracyjne podtalerze. Liczba stołów i nakryć oraz podział wyposażenia między hotel a MAVINCI są ustalane przed wyceną. Zdjęcie pokazuje przykład aranżacji, a nie automatycznie pełny zestaw florystyki i zastawy.\n\nŚwiatło\nDekoracyjne światło podkreśla ściany i wybrane elementy scenografii. Dodatkowo można wykorzystać oprawy o wyglądzie retro. Dobór ilości, kolorów oraz ustawienia zależy od wnętrza. Efekty sceniczne, ruchome światło i realizator prowadzący zmiany podczas programu wymagają osobnego zakresu.\n\nEkran LED i personalizacja\nOpcjonalny ekran LED może prezentować nazwę wydarzenia, planszę powitalną i przygotowaną oprawę filmową. Format ekranu, konstrukcję, miejsce ustawienia, zasilanie, treści i sposób obsługi ustalamy dla konkretnej sali. Ekran nie oznacza automatycznie zamówienia sceny, nagłośnienia ani realizacji koncertu. Możliwe są również personalizowane bannery oraz wycinane postacie 2D na PCV, po ustaleniu projektu i wymiarów.\n\nMontaż i logistyka\nTransport, praca ekipy, montaż i demontaż są kalkulowane wspólnie dla wybranego zestawu. Wyceniając kilka elementów nie naliczamy ponownie tej samej pracy i logistyki. Potrzebujemy planu sali, dostępu do zasilania, godzin rozładunku, montażu i odbioru oraz informacji o ograniczeniach obiektu. W niskich salach dobieramy dekoracje wolnostojące z uwzględnieniem podstaw i instalacji sufitowych.\n\nInspiracje z naszych realizacji\nFilmowe wejście, scenografię gali, dekoracje stołów oraz wykorzystanie LED można zobaczyć w realizacji Gala Oskary Sprzedaży 2023. Sylwester 2024 pokazuje motywy taśmy filmowej i aranżację z fotelem reżysera. Odlotowa 40 prezentuje oprawę światłem i retro. Występy artystyczne, kasyno, DJ i pozostałe atrakcje widoczne na zdjęciach nie są automatycznie częścią tego produktu.\n\nTrzy pakiety aranżacji\nCeny odnoszą się do aranżacji sali około 360 m² dla 90–100 gości, z dekoracją maksymalnie 12 stołów w pakietach obejmujących stoły. Dla innej przestrzeni lub liczby stołów zakres i cenę potwierdzamy ponownie.\n\nBasic — dekor filmowy: 6 000 zł netto\nWejście z czerwonym dywanem i kordonami, scenografia z dostępnych dekoracji filmowych, miejsce do zdjęć z rekwizytami oraz światło dekoracyjne sali. Ilości i rozmieszczenie dobieramy do uzgodnionej aranżacji. Pakiet nie obejmuje dekoracji stołów ani ekranu LED. Oprawy retro dobieramy opcjonalnie zgodnie z zakresem elementu światła.\n\nDekor i stoły: 10 000 zł netto\nCały zakres Basic oraz dekoracja do 12 stołów w uzgodnionym standardzie. Przed realizacją zatwierdzamy kompozycje i dodatki oraz określamy, które tekstylia, podtalerze, kwiaty i zastawę zapewnia MAVINCI, a które hotel. Cena nie oznacza automatycznie pełnej florystyki i całej zastawy widocznej na zdjęciach portfolio.\n\nDekor, stoły i LED 15 m²: 17 000 zł netto\nCały zakres pakietu Dekor i stoły oraz ekran LED o łącznej powierzchni 15 m² do oprawy wizualnej wydarzenia. Proporcje, położenie i konstrukcję dopasowujemy do sali. Przy wysokości 3 m uwzględniamy podstawy i wymagane odstępy — 15 m² nie przesądza o wysokości samego ekranu. Treści oraz sposób obsługi ustalamy przed realizacją. Scena i nagłośnienie nie są częścią tego pakietu.\n\nWybór zakresu i dodatki\nCeny 6 000, 10 000 i 17 000 zł netto są cenami całych, alternatywnych pakietów; nie sumuje się ich. Nowe personalizowane bannery, postacie 2D na PCV i dodatkowe stoły pozostają osobno wycenianymi rozszerzeniami. Logistykę oraz warunki montażu i demontażu doprecyzowujemy w konkretnej ofercie, kalkulując je wspólnie dla wybranego zestawu. Termin i dostępność wyposażenia wymagają potwierdzenia.", "offer_additional_requirements": [{"id": "25033ddb-cc97-46d4-9d21-44ed211a49e2", "title": "PLAN SALI I WYSOKOŚĆ", "category": "place", "description": "Rzut lub zdjęcia sali, rzeczywista wysokość, drzwi, instalacje i układ parkietu. Wymiary dekoracji uwzględniają podstawy oraz konstrukcje."}, {"id": "127e71b5-e6c0-4823-a6c2-6b801097d734", "title": "STOŁY I WYPOSAŻENIE HOTELU", "category": "resources", "description": "Liczba, kształt i wymiary stołów oraz liczba nakryć. Uzgadniamy, kto zapewnia obrusy, serwetki, podtalerze, zastawę i kwiaty."}, {"id": "fa11ba34-2f73-4ad0-bb87-79554069c6d0", "title": "WYBÓR SCENOGRAFII", "category": "resources", "description": "Przed realizacją zatwierdzamy konkretne tła, figury, rekwizyty, ich ilości i rozmieszczenie. Zdjęcia portfolio przedstawiają przykłady."}, {"id": "16c21c27-0f3f-4beb-8c94-bdd361bde702", "title": "PERSONALIZACJA I TREŚCI LED", "category": "resources", "description": "Nazwa wydarzenia, teksty i materiały graficzne do przygotowania projektu. Treści oraz zakres obsługi ekranu ustalamy przed realizacją."}, {"id": "4d8eef1f-9109-416c-88a6-8f85c44021ce", "title": "MONTAŻ I DEMONTAŻ", "category": "power", "description": "Adres, rozładunek, parking, dostęp do sali, zasilanie, godziny montażu i demontażu. Logistyka jest kalkulowana raz dla uzgodnionej aranżacji."}, {"id": "df6ab59f-a668-423b-9db0-1f16a5835dbe", "title": "ZAŁOŻENIA PAKIETÓW", "category": "place", "description": "Ceny dla sali około 360 m² i 90–100 gości. Pakiety ze stołami obejmują dekorację do 12 stołów w uzgodnionym standardzie. Zmiana przestrzeni, liczby stołów lub standardu wymaga potwierdzenia wyceny."}, {"id": "56b5c7f4-e3aa-4b3e-b620-a3be23ac8e03", "title": "EKRAN LED 15 M²", "category": "setup", "description": "Tylko w pakiecie z LED. Proporcje i konstrukcję dobieramy do sali, uwzględniając 3 m wysokości, podstawy i odstępy. Treści, zasilanie i obsługa do uzgodnienia; scena i nagłośnienie nie są w zakresie."}]}'::jsonb)) WHERE id='afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf';
COMMIT;
